import{_ as s,o as i,c as t,l as a,t as o,N as n}from"./chunks/framework.CMqbtke2.js";const f=JSON.parse('{"title":"dir_colors | x-cmd man (man5) | configuration file for dircolors(1)","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | dir_colors - configuration file for dircolors(1)","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"dir_colors | x-cmd man (man5) | configuration file for dircolors(1)"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | dir_colors - configuration file for dircolors(1)"}]]},"headers":[],"params":{"isMan":true,"man":"dir_colors","category":"man5","desc":"configuration file for dircolors(1)"},"relativePath":"man5/dir_colors.md","filePath":"man5/dir_colors.md"}'),r={name:"man5/dir_colors.md"},l={class:"visually-hidden"},d=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>dir_colors - configuration file for dircolors(1)</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The program <strong>ls</strong>(1) uses the environment variable <strong>LS_COLORS</strong> to determine the colors in which the filenames are to be displayed. This environment variable is usually set by a command like</p><blockquote><p>eval `dircolors some_path/dir_colors`</p></blockquote><p>found in a system default shell initialization file, like <em>/etc/profile</em> or <em>/etc/csh.cshrc</em>. (See also <strong>dircolors</strong>(1).) Usually, the file used here is <em>/etc/DIR_COLORS</em> and can be overridden by a <em>.dir_colors</em> file in one&#39;s home directory.</p><p>This configuration file consists of several statements, one per line. Anything right of a hash mark (#) is treated as a comment, if the hash mark is at the beginning of a line or is preceded by at least one whitespace. Blank lines are ignored.</p><p>The <em>global</em> section of the file consists of any statement before the first <strong>TERM</strong> statement. Any statement in the global section of the file is considered valid for all terminal types. Following the global section is one or more <em>terminal-specific</em> sections, preceded by one or more <strong>TERM</strong> statements which specify the terminal types (as given by the <strong>TERM</strong> environment variable) the following declarations apply to. It is always possible to override a global declaration by a subsequent terminal-specific one.</p><p>The following statements are recognized; case is insignificant:</p><dl><dt>*<em>TERM <em>terminal-type</em></em> *</dt><dd>Starts a terminal-specific section and specifies which terminal it applies to. Multiple <strong>TERM</strong> statements can be used to create a section which applies for several terminal types.</dd><dt><strong>COLOR yes|all|no|none|tty</strong></dt><dd>(Slackware only; ignored by GNU <strong>dircolors</strong>(1).) Specifies that colorization should always be enabled (<em>yes</em> or <em>all</em>), never enabled (<em>no</em> or <em>none</em>), or enabled only if the output is a terminal (<em>tty</em>). The default is <em>no</em>.</dd><dt><strong>EIGHTBIT yes|no</strong></dt><dd>(Slackware only; ignored by GNU <strong>dircolors</strong>(1).) Specifies that eight-bit ISO/IEC 8859 characters should be enabled by default. For compatibility reasons, this can also be specified as 1 for <em>yes</em> or 0 for <em>no</em>. The default is <em>no</em>.</dd><dt>*<em>OPTIONS <em>options</em></em> *</dt><dd>(Slackware only; ignored by GNU <strong>dircolors</strong>(1).) Adds command-line options to the default <strong>ls</strong> command line. The options can be any valid <strong>ls</strong> command-line options, and should include the leading minus sign. Note that <strong>dircolors</strong> does not verify the validity of these options.</dd><dt>*<em>NORMAL <em>color-sequence</em></em> *</dt><dd>Specifies the color used for normal (nonfilename) text.</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Synonym:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NORM</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span></span></code></pre></div><dl><dt>*<em>FILE <em>color-sequence</em></em> *</dt><dd>Specifies the color used for a regular file.</dd><dt>*<em>DIR <em>color-sequence</em></em> *</dt><dd>Specifies the color used for directories.</dd><dt>*<em>LINK <em>color-sequence</em></em> *</dt><dd>Specifies the color used for a symbolic link.</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Synonyms:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">LNK</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SYMLINK</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span></span></code></pre></div><dl><dt>*<em>ORPHAN <em>color-sequence</em></em> *</dt><dd>Specifies the color used for an orphaned symbolic link (one which points to a nonexistent file). If this is unspecified, <strong>ls</strong> will use the <strong>LINK</strong> color instead.</dd><dt>*<em>MISSING <em>color-sequence</em></em> *</dt><dd>Specifies the color used for a missing file (a nonexistent file which nevertheless has a symbolic link pointing to it). If this is unspecified, <strong>ls</strong> will use the <strong>FILE</strong> color instead.</dd><dt>*<em>FIFO <em>color-sequence</em></em> *</dt><dd>Specifies the color used for a FIFO (named pipe).</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Synonym:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PIPE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span></span></code></pre></div><dl><dt>*<em>SOCK <em>color-sequence</em></em> *</dt><dd>Specifies the color used for a socket.</dd><dt>*<em>DOOR <em>color-sequence</em></em> *</dt><dd>(Supported since fileutils 4.1) Specifies the color used for a door (Solaris 2.5 and later).</dd><dt>*<em>BLK <em>color-sequence</em></em> *</dt><dd>Specifies the color used for a block device special file.</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Synonym:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">BLOCK</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span></span></code></pre></div><dl><dt>*<em>CHR <em>color-sequence</em></em> *</dt><dd>Specifies the color used for a character device special file.</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Synonym:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">CHAR</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span></span></code></pre></div><dl><dt>*<em>EXEC <em>color-sequence</em></em> *</dt><dd>Specifies the color used for a file with the executable attribute set.</dd><dt>*<em>SUID <em>color-sequence</em></em> *</dt><dd>Specifies the color used for a file with the set-user-ID attribute set.</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Synonym:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SETUID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span></span></code></pre></div><dl><dt>*<em>SGID <em>color-sequence</em></em> *</dt><dd>Specifies the color used for a file with the set-group-ID attribute set.</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Synonym:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SETGID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span></span></code></pre></div><dl><dt>*<em>STICKY <em>color-sequence</em></em> *</dt><dd>Specifies the color used for a directory with the sticky attribute set.</dd><dt>*<em>STICKY_OTHER_WRITABLE <em>color-sequence</em></em> *</dt><dd>Specifies the color used for an other-writable directory with the executable attribute set.</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Synonym:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">OWT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span></span></code></pre></div><dl><dt>*<em>OTHER_WRITABLE <em>color-sequence</em></em> *</dt><dd>Specifies the color used for an other-writable directory without the executable attribute set.</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Synonym:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">OWR</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span></span></code></pre></div><dl><dt>*<em>LEFTCODE <em>color-sequence</em></em> *</dt><dd>Specifies the <em>left code</em> for non-ISO/IEC 6429 terminals (see below).</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Synonym:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">LEFT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span></span></code></pre></div><dl><dt>*<em>RIGHTCODE <em>color-sequence</em></em> *</dt><dd>Specifies the <em>right code</em> for non-ISO/IEC 6429 terminals (see below).</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Synonym:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">RIGHT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span></span></code></pre></div><dl><dt>*<em>ENDCODE <em>color-sequence</em></em> *</dt><dd>Specifies the <em>end code</em> for non-ISO/IEC 6429 terminals (see below).</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Synonym:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">END</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span></span></code></pre></div><dl><dt>*<em>*</em> *<em>extension color-sequence</em></dt><dd>Specifies the color used for any file that ends in <em>extension</em>.</dd><dt><strong>.</strong> <em>extension color-sequence</em></dt><dd>Same as *<em>*</em> *.<em>extension</em>. Specifies the color used for any file that ends in .<em>extension</em>. Note that the period is included in the extension, which makes it impossible to specify an extension not starting with a period, such as <strong>~</strong> for <strong>emacs</strong> backup files. This form should be considered obsolete.</dd></dl><h3 id="iso-iec-6429-ansi-color-sequences" tabindex="-1">ISO/IEC 6429 (ANSI) color sequences <a class="header-anchor" href="#iso-iec-6429-ansi-color-sequences" aria-label="Permalink to &quot;ISO/IEC 6429 (ANSI) color sequences&quot;">​</a></h3><p>Most color-capable ASCII terminals today use ISO/IEC 6429 (ANSI) color sequences, and many common terminals without color capability, including <strong>xterm</strong> and the widely used and cloned DEC VT100, will recognize ISO/IEC 6429 color codes and harmlessly eliminate them from the output or emulate them. <strong>ls</strong> uses ISO/IEC 6429 codes by default, assuming colorization is enabled.</p><p>ISO/IEC 6429 color sequences are composed of sequences of numbers separated by semicolons. The most common codes are:</p><blockquote><hr><p>0 to restore default color 1 for brighter colors 4 for underlined text 5 for flashing text 30 for black foreground 31 for red foreground 32 for green foreground 33 for yellow (or brown) foreground 34 for blue foreground 35 for purple foreground 36 for cyan foreground 37 for white (or gray) foreground 40 for black background 41 for red background 42 for green background 43 for yellow (or brown) background 44 for blue background 45 for purple background 46 for cyan background 47 for white (or gray) background</p><hr></blockquote><p>Not all commands will work on all systems or display devices.</p><p><strong>ls</strong> uses the following defaults:</p><hr><p>NORMAL 0 Normal (nonfilename) text FILE 0 Regular file DIR 32 Directory LINK 36 Symbolic link ORPHAN undefined Orphaned symbolic link MISSING undefined Missing file FIFO 31 Named pipe (FIFO) SOCK 33 Socket BLK 44;37 Block device CHR 44;37 Character device EXEC 35 Executable file</p><hr><p>A few terminal programs do not recognize the default properly. If all text gets colorized after you do a directory listing, change the <strong>NORMAL</strong> and <strong>FILE</strong> codes to the numerical codes for your normal foreground and background colors.</p><h3 id="other-terminal-types-advanced-configuration" tabindex="-1">Other terminal types (advanced configuration) <a class="header-anchor" href="#other-terminal-types-advanced-configuration" aria-label="Permalink to &quot;Other terminal types (advanced configuration)&quot;">​</a></h3><p>If you have a color-capable (or otherwise highlighting) terminal (or printer!) which uses a different set of codes, you can still generate a suitable setup. To do so, you will have to use the <strong>LEFTCODE</strong>, <strong>RIGHTCODE</strong>, and <strong>ENDCODE</strong> definitions.</p><p>When writing out a filename, <strong>ls</strong> generates the following output sequence: <strong>LEFTCODE</strong> <em>typecode</em> <strong>RIGHTCODE</strong> <em>filename</em> <strong>ENDCODE</strong>, where the <em>typecode</em> is the color sequence that depends on the type or name of file. If the <strong>ENDCODE</strong> is undefined, the sequence <strong>LEFTCODE NORMAL RIGHTCODE</strong> will be used instead. The purpose of the left- and rightcodes is merely to reduce the amount of typing necessary (and to hide ugly escape codes away from the user). If they are not appropriate for your terminal, you can eliminate them by specifying the respective keyword on a line by itself.</p><p><strong>NOTE:</strong> If the <strong>ENDCODE</strong> is defined in the global section of the setup file, it <em>cannot</em> be undefined in a terminal-specific section of the file. This means any <strong>NORMAL</strong> definition will have no effect. A different <strong>ENDCODE</strong> can, however, be specified, which would have the same effect.</p><h3 id="escape-sequences" tabindex="-1">Escape sequences <a class="header-anchor" href="#escape-sequences" aria-label="Permalink to &quot;Escape sequences&quot;">​</a></h3><p>To specify control- or blank characters in the color sequences or filename extensions, either C-style \\-escaped notation or <strong>stty</strong>-style ^-notation can be used. The C-style notation includes the following characters:</p><blockquote><hr><p>\\a Bell (ASCII 7) \\b Backspace (ASCII 8) \\e Escape (ASCII 27) \\f Form feed (ASCII 12) \\n Newline (ASCII 10) \\r Carriage Return (ASCII 13) \\t Tab (ASCII 9) \\v Vertical Tab (ASCII 11) \\? Delete (ASCII 127) \\<em>nnn</em> Any character (octal notation) \\x<em>nnn</em> Any character (hexadecimal notation) \\_ Space \\\\ Backslash (\\) \\^ Caret (^) \\# Hash mark (#)</p><hr></blockquote><p>Note that escapes are necessary to enter a space, backslash, caret, or any control character anywhere in the string, as well as a hash mark as the first character.</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><dl><dt><em>/etc/DIR_COLORS</em></dt><dd>System-wide configuration file.</dd><dt><em>~/.dir_colors</em></dt><dd>Per-user configuration file.</dd></dl><p>This page describes the <strong>dir_colors</strong> file format as used in the fileutils-4.1 package; other versions may differ slightly.</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>The default <strong>LEFTCODE</strong> and <strong>RIGHTCODE</strong> definitions, which are used by ISO/IEC 6429 terminals are:</p><blockquote><hr><p>LEFTCODE \\e[ RIGHTCODE m</p><hr></blockquote><p>The default <strong>ENDCODE</strong> is undefined.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>dircolors</strong>(1), <strong>ls</strong>(1), <strong>stty</strong>(1), <strong>xterm</strong>(1)</p>',61);function h(e,c,p,m,g,k){return i(),t("div",null,[a("h1",l,o(e.$params.man),1),d])}const y=s(r,[["render",h]]);export{f as __pageData,y as default};
